calls = 0
attempts = 0
def transport():
    global calls
    calls += 1
    return 2.0
cost = transport()
if cost <= 1.0:
    attempts += 1
RESULT = {"transport_calls": calls, "recorded_attempts": attempts}

class D:
    def __init__(self): self.spent = 0.0
    def send(self, cost):
        if self.spent + cost > 1.0: return False
        self.spent += cost
        return True
a, b = D(), D()
accepted = int(a.send(.75)) + int(b.send(.75))
RESULT = {"accepted_calls": accepted, "physical_total_cost": a.spent+b.spent, "global_cap_exceeded": a.spent+b.spent > 1.0}

class CorruptState(Exception): pass
initializations = 0
transport_calls = 0
def load(): raise CorruptState()
try:
    state = load()
    if state is None: initializations += 1
    transport_calls += 1
    blocked = False
except CorruptState:
    blocked = True
RESULT = {"initializations": initializations, "transport_calls": transport_calls, "blocked": blocked}

